    public static String createTempDir() {
        String ans = null;
        int count = 0;
        while (true) {
            String temp = System.getProperty("java.io.tmpdir");
            if (temp == null) {
                OurDialog.fatal(null, "Error. java.io.tmpdir is not set.");
            }
            String path = temp + File.separator + "alloy" + (count == 0 ? "" : Integer.toString(count));
            File f = new File(path);
            if (f.exists()) {
                count++;
                continue;
            }
            try {
                f.mkdirs();
                if (f.isDirectory()) {
                    ans = Util.canon(path);
                    break;
                }
            } catch (SecurityException ex) {
                // If we can't create the directory, try the next one.
                count++;
            }
        }
        return ans;
    }

    private static String alloyHome;

    public static String getAlloyHome() {
        if (alloyHome == null) {
            alloyHome = createTempDir();
        }
        return alloyHome;
