        return TypedCheck<bool>(verbose, tensor);
      case kTfLiteString:
        return TypedCheck<string>(verbose, tensor);
      default:
        return false;
    }
  }

private:
  template <typename T>
  bool TypedCheck(const bool verbose, const TfLiteTensor& tensor) {
    if (num_elements_ != tensor.num_elements) {
      return false;
    }
    if (verbose) {
      cout << "Checking " << num_elements_ << " elements of type " << typeid(T).name() << endl;
